using Azure.Storage.Blobs;
namespace Narendra4News.API.Services;
public class MediaService(IConfiguration config){
 public async Task<(string Name,string Url)> Upload(IFormFile file,CancellationToken ct){var ext=Path.GetExtension(file.FileName).ToLowerInvariant(); if(!new[]{".jpg",".jpeg",".png",".webp"}.Contains(ext)||file.Length<12||file.Length>5*1024*1024)throw new ArgumentException("Use a JPG, PNG or WEBP image up to 5 MB.");var magic=new byte[12];using(var probe=file.OpenReadStream()){await probe.ReadExactlyAsync(magic,ct);}bool valid=ext switch{".jpg" or ".jpeg"=>magic[0]==0xff&&magic[1]==0xd8,".png"=>magic.AsSpan(0,8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}),".webp"=>System.Text.Encoding.ASCII.GetString(magic,0,4)=="RIFF"&&System.Text.Encoding.ASCII.GetString(magic,8,4)=="WEBP",_=>false};if(!valid)throw new ArgumentException("Invalid image data.");var conn=config["AzureStorage:ConnectionString"]??throw new InvalidOperationException("Storage is not configured");var container=new BlobContainerClient(conn,config["AzureStorage:Container"]??"media");await container.CreateIfNotExistsAsync(cancellationToken:ct);var name=$"{Guid.NewGuid():N}{ext}";var blob=container.GetBlobClient(name);await using var stream=file.OpenReadStream();await blob.UploadAsync(stream,new Azure.Storage.Blobs.Models.BlobUploadOptions{HttpHeaders=new Azure.Storage.Blobs.Models.BlobHttpHeaders{ContentType=ext switch{".png"=>"image/png",".webp"=>"image/webp",_=>"image/jpeg"}}},ct);return(name,$"/api/media/file/{name}");}
 public async Task<(Stream Stream,string ContentType)> Open(string name,CancellationToken ct){if(!System.Text.RegularExpressions.Regex.IsMatch(name,@"^[a-f0-9]{32}\.(jpg|jpeg|png|webp)$"))throw new ArgumentException("Invalid image name");var container=new BlobContainerClient(config["AzureStorage:ConnectionString"],config["AzureStorage:Container"]??"media");var response=await container.GetBlobClient(name).DownloadStreamingAsync(cancellationToken:ct);return(response.Value.Content,response.Value.Details.ContentType??"application/octet-stream");}
 public async Task Delete(string name,CancellationToken ct){var container=new BlobContainerClient(config["AzureStorage:ConnectionString"],config["AzureStorage:Container"]??"media");await container.DeleteBlobIfExistsAsync(name,cancellationToken:ct);}
}
